-- '헤드리스 브라우저 SPA 채용 공고 스크래핑' 스터디 노트에 후속 사례(iframe에 분리된 상세요강
-- 본문 때문에 조용히 잘못된 값이 채워지던 문제와 그 수정)를 이어붙이고, 같은 작업을 Self-Intro
-- 프로젝트 경험의 experience_detail로도 남긴다. content_markdown 추가분은 이스케이프 문제를
-- 원천 차단하기 위해 16진 리터럴(X'...')로 기록한다 (V102~V109 컨벤션 준용).

UPDATE `study`
SET `content_markdown` = CONCAT(`content_markdown`, X''),
    `updated_at` = NOW()
WHERE `slug` = 'headless-browser-spa-job-posting-scraping';

INSERT INTO `experience_detail` (`experience_id`, `content`, `display_order`, `outcome`, `visible`)
SELECT `id`, '채용 공고 자동수집에서 iframe에 분리된 상세요강 본문을 텍스트 추출에 포함', 5,
       '표제어(수행업무·우대사항 등) 부재로 iframe 분리 여부를 재감지하고 하위 프레임 텍스트를 병합해, 개수 기준 완료 판정 때문에 조용히 잘못된 값(엉뚱한 요약 위젯)이 채워지던 지원자격/우대사항 추출 정확도를 개선했습니다.',
       1
FROM `experience` WHERE `title` = '개인 풀스택 포트폴리오 플랫폼 구축 (Self-Intro)';
SET @detail_id = LAST_INSERT_ID();

INSERT INTO `experience_detail_skill` (`experience_detail_id`, `skill_id`, `list_order`)
SELECT @detail_id, `id`, ROW_NUMBER() OVER (ORDER BY `id`) - 1
FROM `skill` WHERE `name` IN ('Java', 'Spring Boot', 'Playwright');

INSERT INTO `study_experience_detail` (`study_id`, `experience_detail_id`)
SELECT `id`, @detail_id FROM `study` WHERE `slug` = 'headless-browser-spa-job-posting-scraping';
